Lemma testbit_high_small : forall x k n, 0 <= x < 2^k -> 0 <= k <= n -> Z.testbit x n = false.
Proof.
  intros x k n Hx Hk. replace x with (x mod 2^k) by (apply Z.mod_small; lia).
  rewrite Z.testbit_mod_pow2 by lia. replace (n <? k) with false by (symmetry; apply Z.ltb_ge; lia). reflexivity.
Qed.

Lemma small_of_testbit : forall x k, 0 <= x -> 0 <= k -> (forall n, k <= n -> Z.testbit x n = false) -> x < 2^k.
Proof.
  intros x k Hx Hk H. replace x with (x mod 2^k). { apply Z.mod_pos_bound. lia. }
  apply Z.bits_inj'. intros n Hn. rewrite Z.testbit_mod_pow2 by lia.
  destruct (Z.lt_ge_cases n k) as [L|G].
  - replace (n <? k) with true by (symmetry; apply Z.ltb_lt; lia). reflexivity.
  - replace (n <? k) with false by (symmetry; apply Z.ltb_ge; lia). symmetry. apply H. lia.
Qed.

Lemma lor_small : forall a b k, 0 <= a < 2^k -> 0 <= b < 2^k -> 0 <= k -> 0 <= Z.lor a b < 2^k.
Proof.
  intros a b k Ha Hb Hk. split. { apply Z.lor_nonneg; lia. }
  apply small_of_testbit; [apply Z.lor_nonneg; lia | lia |]. intros n Hn. rewrite Z.lor_spec.
  rewrite (testbit_high_small a k n), (testbit_high_small b k n) by lia. reflexivity.
Qed.
Lemma lxor_small : forall a b k, 0 <= a < 2^k -> 0 <= b < 2^k -> 0 <= k -> 0 <= Z.lxor a b < 2^k.
Proof.
  intros a b k Ha Hb Hk. split. { apply Z.lxor_nonneg; lia. }
  apply small_of_testbit; [apply Z.lxor_nonneg; lia | lia |]. intros n Hn. rewrite Z.lxor_spec.
  rewrite (testbit_high_small a k n), (testbit_high_small b k n) by lia. reflexivity.
Qed.
Lemma land_small_l : forall a b k, 0 <= a < 2^k -> 0 <= b -> 0 <= k -> 0 <= Z.land a b < 2^k.
Proof.
  intros a b k Ha Hb Hk. split. { apply Z.land_nonneg; lia. }
  apply small_of_testbit; [apply Z.land_nonneg; lia | lia |]. intros n Hn. rewrite Z.land_spec.
  rewrite (testbit_high_small a k n) by lia. reflexivity.
Qed.

Lemma land_lo_hi : forall a b k, 0 <= a < 2^k -> 0 <= k -> Z.land a (b * 2^k) = 0.
Proof.
  intros a b k Ha Hk. apply Z.bits_inj_0. intros n. rewrite Z.land_spec.
  destruct (Z.lt_ge_cases n 0) as [Hn|Hn]. { rewrite Z.testbit_neg_r by lia. reflexivity. }
  destruct (Z.lt_ge_cases n k) as [Lk|Gk].
  - rewrite Z.mul_pow2_bits by lia. rewrite (Z.testbit_neg_r b) by lia. apply Bool.andb_false_r.
  - rewrite (testbit_high_small a k n) by lia. reflexivity.
Qed.

Lemma lor_lo_hi : forall a b k, 0 <= a < 2^k -> 0 <= b -> 0 <= k -> Z.lor a (b * 2^k) = a + b * 2^k.
Proof.
  intros a b k Ha Hb Hk. pose proof (Z.add_lor_land a (b * 2^k)) as E. rewrite land_lo_hi in E by lia. lia.
Qed.
Lemma lxor_lo_hi : forall a b k, 0 <= a < 2^k -> 0 <= b -> 0 <= k -> Z.lxor a (b * 2^k) = a + b * 2^k.
Proof. intros a b k Ha Hb Hk. symmetry. apply Z.add_nocarry_lxor. apply land_lo_hi; lia. Qed.
