Lemma bw_lor_split : forall k a b c d, 0 <= a < 2^k -> 0 <= c < 2^k -> 0 <= b -> 0 <= d -> 0 <= k ->
  Z.lor (a + b * 2^k) (c + d * 2^k) = Z.lor a c + Z.lor b d * 2^k.
Proof.
  intros k a b c d Ha Hc Hb Hd Hk.
  rewrite <- (lor_lo_hi a b k), <- (lor_lo_hi c d k) by lia.
  rewrite <- (lor_lo_hi (Z.lor a c) (Z.lor b d) k); [| apply lor_small; lia | apply Z.lor_nonneg; lia | lia].
  rewrite <- !Z.shiftl_mul_pow2 by lia. rewrite Z.shiftl_lor.
  rewrite !Z.lor_assoc. f_equal. rewrite <- !Z.lor_assoc. f_equal. apply Z.lor_comm.
Qed.

Lemma u32le_sum : forall c0 c1 c2 c3, 0 <= c0 < 256 -> 0 <= c1 < 256 -> 0 <= c2 < 256 -> 0 <= c3 < 256 ->
