Definition M64 : Z := 18446744073709551615.
(* [comment removed for export] *)
Definition eqw_code (x0 x1 x2 x3 : Z) : Z :=
  Z.lor (Z.lor (Z.land (Z.shiftl x1 8) M64) x0) (Z.lor (Z.land (Z.shiftl x2 16) M64) (Z.land (bv_swrap 32 (Z.shiftl x3 24)) M64)).
Definition hi32 (x3 : Z) : Z := if x3 <? 128 then 0 else 4294967295.

Lemma land_M64 : forall x, 0 <= x < 2^64 -> Z.land x M64 = x.
Proof. intros x Hx. change M64 with (Z.ones 64). rewrite Z.land_ones by lia. apply Z.mod_small. lia. Qed.

Lemma sext24_eq : forall x3, 0 <= x3 < 256 ->
  Z.land (bv_swrap 32 (Z.shiftl x3 24)) M64 = Z.shiftl x3 24 + hi32 x3 * 2^32.
Proof.
  intros x3 H3. change M64 with (Z.ones 64). rewrite Z.land_ones by lia. rewrite Z.shiftl_mul_pow2 by lia.
  unfold hi32, bv_swrap, bv_wrap, bv_half_modulus, bv_modulus.
  change (2 ^ Z.of_N 32) with (2^32) in *.
  destruct (Z.ltb_spec x3 128).
  - rewrite (Z.mod_small (x3 * 2^24 + 2^32 `div` 2)) by (cbn; lia). rewrite Z.mod_small by (cbn; lia). lia.
  - Z.div_mod_to_equations. nia.
Qed.

Lemma hi32_range : forall x3, 0 <= hi32 x3 < 2^32.
Proof. intros x3. unfold hi32. destruct (x3 <? 128); lia. Qed.

