Lemma testbit7_byte : forall c, 0 <= c < 256 -> Z.testbit c 7 = negb (c <? 128).
Proof.
  intros c Hc. destruct (Z.ltb_spec c 128).
  - cbn [negb]. apply Z.testbit_false; [lia|]. rewrite Z.div_small by lia. reflexivity.
  - cbn [negb]. apply Z.testbit_true; [lia|].
    replace (c / 2^7) with 1 by (apply Z.div_unique with (r := c - 128); lia). reflexivity.
Qed.

(* [comment removed for export] *)
Lemma ieq_byte3_hi : forall x3 y3, 0 <= x3 < 256 -> 0 <= y3 < 256 ->
  Z.land (Z.lxor x3 y3) 223 = 0 -> hi32 x3 = hi32 y3.
Proof.
  intros x3 y3 Hx Hy E.
  assert (B : Z.testbit (Z.land (Z.lxor x3 y3) 223) 7 = false) by (rewrite E; apply Z.bits_0).
  rewrite Z.land_spec, Z.lxor_spec in B. rewrite (testbit7_byte x3), (testbit7_byte y3) in B by lia.
  replace (Z.testbit 223 7) with true in B by reflexivity.
  unfold hi32. destruct (x3 <? 128), (y3 <? 128); cbn in B; try reflexivity; discriminate.
Qed.
