Lemma ieq4_bytes : forall x0 x1 x2 x3 y0 y1 y2 y3,
  0 <= x0 < 256 -> 0 <= x1 < 256 -> 0 <= x2 < 256 -> 0 <= x3 < 256 ->
  0 <= y0 < 256 -> 0 <= y1 < 256 -> 0 <= y2 < 256 -> 0 <= y3 < 256 ->
  (Z.land (Z.lxor (u32le x0 x1 x2 x3) (u32le y0 y1 y2 y3)) 3755991007 = 0
