Ltac win_loadH WIN q :=
  lazymatch type of WIN with bytes_at _ ?mx ?it0 ?bs =>
    let b := fresh "b" in let N := fresh "N" in let RD := fresh "RD" in let BR := fresh "BR" in
    destruct (win_byte _ _ _ q WIN ltac:(lia)) as [b N];
    pose proof (zb_range b) as BR; unfold zb in BR;
    pose proof (u8ro_read rsegs _ it0 bs (q - it0) b (Z_to_bv 64 q) WIN N ltac:(lia) ltac:(symmetry; apply wa_of_Z_to_bv; lia)) as RD;
    step; clear RD; change (zxb b) with (Z_to_bv 64 (zb b)); fold (zb b) in BR
  end.

Definition dig_post_v (v : Z) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 (bv_swrap 32 v)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [] m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ bytes_at rsegs m' P bs.

Lemma dig1_acc : forall r c, 0 <= r < 2^32 -> 0 <= c < 256 ->
  Z_to_bv 64 (bv_swrap 32 (bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_unsigned (Z_to_bv 64 (bv_swrap 32 r))) 2 + bv_swrap 32 r))
                           + bv_unsigned (Z_to_bv 64 (Z.lor (bv_unsigned (Z_to_bv 64 c)) 32))))
