Lemma dig_loop2 : forall k j rax sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P : Z) (bs : list byte) (r : Z),
  (length bs - j = k)%nat -> (j < length bs)%nat -> 0 <= r < 2^32 ->
  bytes_at rsegs m P bs -> P + Z.of_nat (length bs) < 2^64 -> mem_inv rsegs m ->
  evt rsegs (dig_post_v (ft_dig1 r (zbytes (skipn j bs))) rax sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs m)
    (MS (mkR rax sp gp tp t0 t1 t2 s0 s1 (wz (P + Z.of_nat j)) (wz (P + Z.of_nat (length bs))) (Z_to_bv 64 (bv_swrap 32 r)) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
