Lemma skipn_4 : forall {X} (l : list X) j x0 x1 x2 x3,
  nth_error l j = Some x0 -> nth_error l (S j) = Some x1 -> nth_error l (S (S j)) = Some x2 -> nth_error l (S (S (S j))) = Some x3 ->
  skipn j l = x0 :: x1 :: x2 :: x3 :: skipn (j + 4) l.
Proof.
  intros X l j x0 x1 x2 x3 N0 N1 N2 N3.
  rewrite (skipn_at_nth l j x0 N0), (skipn_at_nth l (S j) x1 N1), (skipn_at_nth l _ x2 N2), (skipn_at_nth l _ x3 N3).
  replace (j + 4)%nat with (S (S (S (S j)))) by lia. reflexivity.
Qed.

