Definition digest_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  dig_post_v (ft_digest (zbytes bs)) ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs m.

Definition digest_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P : Z) (bs : list byte),
  bytes_at rsegs m P bs -> P + Z.of_nat (length bs) < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (digest_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz P) (wz (Z.of_nat (length bs))) a2 a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FT_DIGEST) fc None m (seg_rom rsegs)).

