Definition eq_post_v (v : bool) (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P Q : Z) (bs cs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (if v then 1 else 0)) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [] m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ bytes_at rsegs m' P bs /\ bytes_at rsegs m' Q cs.

Lemma seqz_bytetest : forall x y, 0 <= x < 256 -> 0 <= y < 256 ->
  v_sltiu (Z_to_bv 64 (Z.land (bv_unsigned (Z_to_bv 64 (Z.lxor (bv_unsigned (Z_to_bv 64 x)) (bv_unsigned (Z_to_bv 64 y))))) 223)) 1
  = wz (if Z.land (Z.lxor x y) 223 =? 0 then 1 else 0).
Proof.
  intros x y Hx Hy. unfold v_sltiu, wz. rewrite (unsigned_lit x), (unsigned_lit y) by lia.
  pose proof (lxor_small x y 8 ltac:(lia) ltac:(lia) ltac:(lia)) as L.
  rewrite (unsigned_lit (Z.lxor x y)) by lia.
  pose proof (land_small_l (Z.lxor x y) 223 8 ltac:(lia) ltac:(lia) ltac:(lia)) as L2.
  rewrite unsigned_lit by lia. change (bv_wrap 64 1) with 1.
  destruct (Z.land (Z.lxor x y) 223 =? 0) eqn:E.
  - apply Z.eqb_eq in E. rewrite E. reflexivity.
  - apply Z.eqb_neq in E. replace (_ <? 1) with false by (symmetry; apply Z.ltb_ge; lia). reflexivity.
Qed.

Lemma eq_loop2 : forall k j rax sp gp tp t0 t1 t2 s0 s1 a1 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P Q : Z) (bs cs : list byte),
  (length bs - j = k)%nat -> (j < length bs)%nat -> length cs = length bs ->
  bytes_at rsegs m P bs -> bytes_at rsegs m Q cs -> P + Z.of_nat (length bs) < 2^64 -> Q + Z.of_nat (length cs) < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (eq_post_v (ft_ieqb (zbytes (skipn j bs)) (zbytes (skipn j cs))) rax sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P Q bs cs m)
    (MS (mkR rax sp gp tp t0 t1 t2 s0 s1 (wz (P + Z.of_nat j)) a1 (wz (Q + Z.of_nat j)) (wz (Z.of_nat (length bs) - Z.of_nat j - 1)) a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 0x3c088) fc None m (seg_rom rsegs)).
Proof.
