Lemma mg7 : forall d, 0 <= d < 2^32 ->
  Z_to_bv 64 (Z.shiftr (bv_unsigned (Z_to_bv 64 ((d - d * 2139628917 / 2^32) / 2 + d * 2139628917 / 2^32))) 10) = Z_to_bv 64 (d / 1367).
Proof.
  intros d Hd. f_equal. pose proof (mg_t_range d Hd). rewrite unsigned_lit by (Z.div_mod_to_equations; lia).
  rewrite Z.shiftr_div_pow2 by lia. apply mod1367_magic. exact Hd.
Qed.
Lemma mg9 : forall d, 0 <= d < 2^32 ->
  Z_to_bv 64 (bv_swrap 32 (bv_unsigned (Z_to_bv 64 (bv_swrap 32 d)) - bv_unsigned (Z_to_bv 64 (bv_unsigned (Z_to_bv 64 (d / 1367)) * 1367))))
