Lemma mg_zext32 : forall e, 0 <= e < 2^32 ->
  Z_to_bv 64 (Z.shiftr (bv_unsigned (Z_to_bv 64 (Z.shiftl (bv_unsigned (Z_to_bv 64 e)) 32))) 32) = Z_to_bv 64 e.
Proof.
  intros e He. f_equal. rewrite (unsigned_lit e) by lia.
  rewrite Z.shiftl_mul_pow2 by lia. rewrite unsigned_lit by lia.
  rewrite Z.shiftr_div_pow2 by lia. rewrite Z.div_mul by lia. reflexivity.
Qed.

Definition S2F_STACK : Z := 48.

Definition s2f_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P lo : Z) (bs : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz (ft_lookup (zbytes bs))) a1 a2 a3 a4 a5 a6 a7
                  s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ bytes_at rsegs m' P bs /\ FT m'.

(* [comment removed for export] *)
Definition s2f_stmt : Prop :=
  forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (P lo : Z) (bs : list byte),
  bytes_at rsegs m P bs -> FT m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + S2F_STACK <= bv_unsigned sp -> 0xb4000 <= lo ->
  P + Z.of_nat (length bs) <= lo ->
  mem_inv rsegs m ->
  evt rsegs (s2f_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P lo bs m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz G_FIELD_TABLE) (wz P) (wz (Z.of_nat (length bs))) a3 a4 a5 a6 a7
              s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_FT_S2F) fc None m (seg_rom rsegs)).

